1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.mapstruct.Named;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	import org.springframework.samples.petclinic.rest.validation.E164Telephone;
13	import org.springframework.samples.petclinic.util.AddressNormalizer;
14	import org.springframework.samples.petclinic.util.Regions;
15	
16	import java.time.LocalDate;
17	import java.util.Collection;
18	import java.util.List;
19	
20	/**
21	 * Maps Owner & OwnerDto using Mapstruct
22	 */
23	@Mapper(uses = PetMapper.class)
24	public interface OwnerMapper {
25	
26	    @Mapping(target = "selfLink", expression = "java(formatSelfLink(owner))")
27	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
28	    @Mapping(target = "salutation", expression = "java(formatSalutation(owner))")
29	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
30	    @Mapping(target = "telephoneDisplay", expression = "java(formatTelephoneDisplay(owner))")
31	    @Mapping(target = "fiscalYear", expression = "java(formatFiscalYear(owner))")
32	    @Mapping(target = "membershipPoints", expression = "java(formatMembershipPoints(owner))")
33	    @Mapping(target = "membershipLevel", expression = "java(formatMembershipLevel(owner))")
34	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
35	    @Mapping(target = "timezone", expression = "java(formatTimezone(owner))")
36	    @Mapping(target = "bulkSignupWarning", expression = "java(formatBulkSignupWarning(owner))")
37	    @Mapping(target = "capacityWarning", expression = "java(formatCapacityWarning(owner))")
38	    @Mapping(target = "possibleDuplicate", expression = "java(formatPossibleDuplicate(owner))")
39	    @Mapping(target = "contactPreference", expression = "java(formatContactPreference(owner))")
40	    @Mapping(target = "ageBand", expression = "java(formatAgeBand(owner))")
41	    @Mapping(target = "ownerSegment", expression = "java(formatOwnerSegment(owner))")
42	    OwnerDto toOwnerDto(Owner owner);
43	
44	    /**
45	     * Derive an owner's marketing segment, formatted {@code "<TIER>_<AREA>"}. The tier is
46	     * {@code "PREMIUM"} when the owner's {@code membershipLevel} (see
47	     * {@link #formatMembershipLevel(Owner)}) is {@code 3} or more, otherwise {@code "STANDARD"}.
48	     * The area is {@code "METRO"} when the owner's locality (see {@link #formatLocality(Owner)}) is
49	     * a known region (NSW, VIC or QLD), otherwise {@code "REGIONAL"}. Returns one of
50	     * {@code "PREMIUM_METRO"}, {@code "PREMIUM_REGIONAL"}, {@code "STANDARD_METRO"} or
51	     * {@code "STANDARD_REGIONAL"}; {@code null} only when the owner is {@code null}.
52	     */
53	    default String formatOwnerSegment(Owner owner) {
54	        if (owner == null) {
55	            return null;
56	        }
57	        Integer level = formatMembershipLevel(owner);
58	        String tier = level != null && level >= 3 ? "PREMIUM" : "STANDARD";
59	        String area = Regions.isKnownRegion(formatLocality(owner)) ? "METRO" : "REGIONAL";
60	        return tier + "_" + area;
61	    }
62	
63	    /**
64	     * Resolve an owner's possible-duplicate flag, coalescing a {@code null} stored value
65	     * (e.g. for owners created before the flag existed) to {@code false} so the response
66	     * always carries an explicit boolean.
67	     */
68	    default Boolean formatPossibleDuplicate(Owner owner) {
69	        if (owner == null) {
70	            return null;
71	        }
72	        return Boolean.TRUE.equals(owner.getPossibleDuplicate());
73	    }
74	
75	    /**
76	     * Derive an owner's age band from its {@code birthDate}, measured as the owner's age in whole
77	     * years on its {@code registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"} from 18
78	     * through 64, and {@code "SENIOR"} at 65 and over. Returns {@code null} when the owner, its
79	     * birth date or its registration date is absent, since the band cannot be derived without both
80	     * dates.
81	     */
82	    default String formatAgeBand(Owner owner) {
83	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
84	            return null;
85	        }
86	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
87	        if (age < 18) {
88	            return "MINOR";
89	        }
90	        if (age < 65) {
91	            return "ADULT";
92	        }
93	        return "SENIOR";
94	    }
95	
96	    /**
97	     * Derive an owner's preferred contact channel from its stored contact details:
98	     * {@code "EMAIL"} when a (non-blank) email address is present, otherwise {@code "PHONE"}.
99	     */
100	    default String formatContactPreference(Owner owner) {
101	        if (owner == null) {
102	            return null;
103	        }
104	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
105	        return hasEmail ? "EMAIL" : "PHONE";
106	    }
107	
108	    /**
109	     * Resolve an owner's bulk-signup warning flag, coalescing a {@code null} stored value
110	     * (e.g. for owners created before the flag existed) to {@code false} so the response
111	     * always carries an explicit boolean.
112	     */
113	    default Boolean formatBulkSignupWarning(Owner owner) {
114	        if (owner == null) {
115	            return null;
116	        }
117	        return Boolean.TRUE.equals(owner.getBulkSignupWarning());
118	    }
119	
120	    /**
121	     * Resolve an owner's capacity-warning flag, coalescing a {@code null} stored value
122	     * (e.g. for owners created before the flag existed) to {@code false} so the response
123	     * always carries an explicit boolean.
124	     */
125	    default Boolean formatCapacityWarning(Owner owner) {
126	        if (owner == null) {
127	            return null;
128	        }
129	        return Boolean.TRUE.equals(owner.getCapacityWarning());
130	    }
131	
132	    /**
133	     * Derive an owner's locality from its {@code memberId}: the leading {@code <REGION>} segment
134	     * (the run of letters before the 2-digit fiscal year), which is the region code derived from
135	     * the owner's postcode. For an owner that has not yet been assigned a member id, the region is
136	     * derived directly from the postcode (see {@link Regions#forPostcode}), yielding the same value
137	     * the id would carry. Returns {@code null} only when the owner itself is {@code null}.
138	     */
139	    default String formatLocality(Owner owner) {
140	        if (owner == null) {
141	            return null;
142	        }
143	        String region = memberIdRegion(owner.getMemberId());
144	        if (region != null) {
145	            return region;
146	        }
147	        return Regions.forPostcode(owner.getPostcode());
148	    }
149	
150	    /**
151	     * The leading {@code <REGION>} segment of a {@code memberId}: its maximal prefix of letters,
152	     * which precedes the 2-digit fiscal year. Returns {@code null} when the member id is
153	     * {@code null} (so callers can fall back to deriving the region from the postcode).
154	     *
155	     * <p>Declared {@code private} so MapStruct does not pick it up as an automatic {@code String ->
156	     * String} conversion and apply it to every string property.
157	     */
158	    private String memberIdRegion(String memberId) {
159	        if (memberId == null) {
160	            return null;
161	        }
162	        int i = 0;
163	        while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
164	            i++;
165	        }
166	        return memberId.substring(0, i);
167	    }
168	
169	    /**
170	     * Derive an owner's timezone as the IANA name mapped from its locality/region via a fixed
171	     * region-to-timezone table (see {@link Regions#timezoneForRegion}): NSW -> Australia/Sydney,
172	     * VIC -> Australia/Melbourne, QLD -> Australia/Brisbane. Returns {@code null} when the owner
173	     * is {@code null} or its region is not in the table.
174	     */
175	    default String formatTimezone(Owner owner) {
176	        if (owner == null) {
177	            return null;
178	        }
179	        return Regions.timezoneForRegion(formatLocality(owner));
180	    }
181	
182	    /**
183	     * Compute an owner's membership points. Points start at {@code 0} and gain: {@code 2} when an
184	     * email address is present; {@code 1} when the owner has no namesakes (its
185	     * {@code namesakeCount} is {@code 0}); {@code 2} for a household of three or more members (the
186	     * owner plus its pets); and {@code 3} when the owner's tenure (the number of fiscal years
187	     * elapsed since its {@code registrationDate}'s fiscal year) exceeds {@code 1}. A null or absent
188	     * namesake count is treated as not being zero, so it contributes nothing.
189	     */
190	    default Integer formatMembershipPoints(Owner owner) {
191	        if (owner == null) {
192	            return null;
193	        }
194	        int points = 0;
195	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
196	        if (hasEmail) {
197	            points += 2;
198	        }
199	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
200	        if (uniqueName) {
201	            points += 1;
202	        }
203	        int householdSize = 1 + (owner.getPets() == null ? 0 : owner.getPets().size());
204	        if (householdSize >= 3) {
205	            points += 2;
206	        }
207	        LocalDate registrationDate = owner.getRegistrationDate();
208	        if (registrationDate != null
209	            && fiscalYearEndYear(LocalDate.now()) - fiscalYearEndYear(registrationDate) > 1) {
210	            points += 3;
211	        }
212	        return points;
213	    }
214	
215	    /**
216	     * Determine an owner's membership level, a number from {@code 1} to {@code 4} derived from its
217	     * membership points (see {@link #formatMembershipPoints(Owner)}): level {@code 1} for
218	     * {@code 0}-{@code 1} points, {@code 2} for {@code 2}-{@code 3}, {@code 3} for {@code 4}-{@code 5}
219	     * and {@code 4} for {@code 6} or more.
220	     *
221	     * <p>The level is then capped by the owner's {@code membershipLevelCap} when one is present (see
222	     * {@link Owner#getMembershipLevelCap()}): a new owner's level may not exceed one above the
223	     * current maximum level among its existing household members, so the returned value is the
224	     * smaller of the points-derived level and the cap. A {@code null} cap means no household ceiling
225	     * applies and the points-derived level is returned unchanged.
226	     */
227	    default Integer formatMembershipLevel(Owner owner) {
228	        if (owner == null) {
229	            return null;
230	        }
231	        int points = formatMembershipPoints(owner);
232	        int level;
233	        if (points <= 1) {
234	            level = 1;
235	        }
236	        else if (points <= 3) {
237	            level = 2;
238	        }
239	        else if (points <= 5) {
240	            level = 3;
241	        }
242	        else {
243	            level = 4;
244	        }
245	        Integer cap = owner.getMembershipLevelCap();
246	        if (cap != null && cap < level) {
247	            return cap;
248	        }
249	        return level;
250	    }
251	
252	    /**
253	     * Format an owner's fiscal year as {@code "FY<YY>"}, where {@code YY} is the 2-digit fiscal
254	     * year. The value is read from the {@code <FY>} segment of the owner's {@code memberId} (the
255	     * two digits immediately after the leading region segment), which is the fiscal year the
256	     * owner's (business-day-adjusted) {@code registrationDate} falls in. The fiscal year starts on
257	     * 1 July and is named by the calendar year in which it ends, so a registration date of
258	     * {@code 2026-07-01} is {@code "FY27"} while {@code 2026-06-30} is {@code "FY26"}. For an owner
259	     * with no member id yet, it falls back to deriving the fiscal year directly from the
260	     * registration date. Returns {@code null} when the owner, or both its member id and
261	     * registration date, are absent.
262	     */
263	    default String formatFiscalYear(Owner owner) {
264	        if (owner == null) {
265	            return null;
266	        }
267	        String memberId = owner.getMemberId();
268	        if (memberId != null) {
269	            int start = memberIdRegion(memberId).length();
270	            if (start + 2 <= memberId.length()) {
271	                return "FY" + memberId.substring(start, start + 2);
272	            }
273	        }
274	        if (owner.getRegistrationDate() == null) {
275	            return null;
276	        }
277	        return String.format("FY%02d", fiscalYearEndYear(owner.getRegistrationDate()) % 100);
278	    }
279	
280	    /**
281	     * The calendar year in which {@code date}'s fiscal year ends, used as the fiscal year's name.
282	     * The fiscal year starts on 1 July, so a date in July through December belongs to the fiscal
283	     * year ending the following calendar year, while January through June belongs to the one
284	     * ending in the current calendar year.
285	     */
286	    default int fiscalYearEndYear(LocalDate date) {
287	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
288	    }
289	
290	    /**
291	     * Format an owner's stored E.164 telephone for humans as the country code, a space, then the
292	     * national digits grouped in threes, e.g. {@code "+61412345678"} becomes
293	     * {@code "+61 412 345 678"} (see {@link E164Telephone#toDisplay}). The raw {@code telephone}
294	     * is left in E.164 form. Returns {@code null} when the owner or its telephone is absent.
295	     */
296	    default String formatTelephoneDisplay(Owner owner) {
297	        if (owner == null) {
298	            return null;
299	        }
300	        return E164Telephone.toDisplay(owner.getTelephone());
301	    }
302	
303	    /**
304	     * Compose an owner's salutation as its {@code title} followed by a single space and the
305	     * last name (e.g. {@code "DR Franklin"}). When no title was supplied (null or blank) the
306	     * salutation is just the last name. Returns {@code null} when the owner is {@code null}.
307	     */
308	    default String formatSalutation(Owner owner) {
309	        if (owner == null) {
310	            return null;
311	        }
312	        String title = owner.getTitle();
313	        if (title == null || title.trim().isEmpty()) {
314	            return owner.getLastName();
315	        }
316	        return title + " " + owner.getLastName();
317	    }
318	
319	    /**
320	     * Build a link to an owner's own resource, formed as {@code "/api/owners/"} followed by the
321	     * owner's id. Returns {@code null} when the owner or its id is absent, since the link cannot
322	     * be formed without an id.
323	     */
324	    default String formatSelfLink(Owner owner) {
325	        if (owner == null || owner.getId() == null) {
326	            return null;
327	        }
328	        return "/api/owners/" + owner.getId();
329	    }
330	
331	    /**
332	     * Format an owner's name as {@code "LastName, FirstName"} from the stored names.
333	     */
334	    default String formatDisplayName(Owner owner) {
335	        if (owner == null) {
336	            return null;
337	        }
338	        return owner.getLastName() + ", " + owner.getFirstName();
339	    }
340	
341	    /**
342	     * Format an owner's initials as the upper-cased first letters of the first and last
343	     * names, dot-separated with a trailing dot, e.g. {@code "J.S."}.
344	     */
345	    default String formatInitials(Owner owner) {
346	        if (owner == null) {
347	            return null;
348	        }
349	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
350	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
351	    }
352	
353	    Owner toOwner(OwnerDto ownerDto);
354	
355	    @Mapping(target = "id", ignore = true)
356	    @Mapping(target = "pets", ignore = true)
357	    @Mapping(target = "namesakeCount", ignore = true)
358	    @Mapping(target = "bulkSignupWarning", ignore = true)
359	    @Mapping(target = "capacityWarning", ignore = true)
360	    @Mapping(target = "possibleDuplicate", ignore = true)
361	    @Mapping(target = "possibleDuplicateOf", ignore = true)
362	    @Mapping(target = "membershipLevelCap", ignore = true)
363	    @Mapping(target = "address", expression = "java(composeAddress(ownerDto))")
364	    @Mapping(target = "addressLine1", source = "addressLine1", qualifiedByName = "normalizeAddress")
365	    @Mapping(target = "addressLine2", source = "addressLine2", qualifiedByName = "normalizeAddress")
366	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
367	    @Mapping(target = "email", source = "email", qualifiedByName = "normalizeEmail")
368	    Owner toOwner(OwnerFieldsDto ownerDto);
369	
370	    /**
371	     * Normalize a postal address for storage into its canonical form (see
372	     * {@link AddressNormalizer}), so it is persisted and returned the same way regardless of
373	     * the formatting supplied by the caller. {@code @Named} keeps this out of MapStruct's
374	     * automatic method selection, so it only runs where a mapping explicitly references it via
375	     * {@code qualifiedByName}.
376	     */
377	    @Named("normalizeAddress")
378	    default String normalizeAddress(String address) {
379	        return AddressNormalizer.normalize(address);
380	    }
381	
382	    /**
383	     * Compose the single stored/returned {@code address} from whichever address fields the request
384	     * supplies, preferring the structured form. When a non-blank {@code addressLine1} is present the
385	     * composed value is the normalized {@code addressLine1} (see {@link AddressNormalizer}), with a
386	     * single space and the normalized {@code addressLine2} appended when {@code addressLine2} is
387	     * present; otherwise it falls back to the normalized flat {@code address}. This keeps everything
388	     * that reads the stored address consistent regardless of which form the caller used.
389	     */
390	    default String composeAddress(OwnerFieldsDto ownerDto) {
391	        if (ownerDto == null) {
392	            return null;
393	        }
394	        String line1 = ownerDto.getAddressLine1();
395	        if (line1 != null && !line1.trim().isEmpty()) {
396	            String composed = AddressNormalizer.normalize(line1);
397	            String line2 = ownerDto.getAddressLine2();
398	            if (line2 != null && !line2.trim().isEmpty()) {
399	                composed = composed + " " + AddressNormalizer.normalize(line2);
400	            }
401	            return composed;
402	        }
403	        return AddressNormalizer.normalize(ownerDto.getAddress());
404	    }
405	
406	    /**
407	     * Normalize a telephone number for storage into E.164 form (see {@link E164Telephone}).
408	     * The requirement that a valid E.164 number can be formed is enforced separately by
409	     * {@code TelephoneValidation}, so for already-validated input this returns the E.164
410	     * string; it is idempotent, so re-normalizing a stored value yields the same value.
411	     * {@code @Named} keeps this out of MapStruct's automatic method selection, so it only
412	     * runs where a mapping explicitly references it via {@code qualifiedByName}.
413	     */
414	    @Named("normalizeTelephone")
415	    default String normalizeTelephone(String telephone) {
416	        return E164Telephone.normalize(telephone);
417	    }
418	
419	    /**
420	     * Normalize an email address for storage by lower-casing it, so it is persisted and
421	     * returned in a canonical form regardless of the casing supplied by the caller.
422	     * Syntactic validity is enforced separately by the {@code @Email} constraint on the DTO.
423	     * {@code @Named} keeps this out of MapStruct's automatic method selection, so it only
424	     * runs where a mapping explicitly references it via {@code qualifiedByName}.
425	     */
426	    @Named("normalizeEmail")
427	    default String normalizeEmail(String email) {
428	        return email == null ? null : email.toLowerCase();
429	    }
430	
431	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
432	
433	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
434	
435	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
436	        OwnerPageDto ownerPageDto = new OwnerPageDto();
437	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
438	        ownerPageDto.setPage(ownerPage.getNumber());
439	        ownerPageDto.setSize(ownerPage.getSize());
440	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
441	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
442	        return ownerPageDto;
443	    }
444	}
