254	    /**
255	     * Build a unified {@code memberId} of the form {@code <REGION><FY><HASH8><CHK>}: the region code
256	     * derived from the owner's postcode (see {@link Regions#forPostcode}), the 2-digit fiscal year of
257	     * the owner's (business-day-adjusted) registration date, {@code HASH8} — the first eight
258	     * upper-case hex characters of the SHA-256 of the owner's normalized telephone concatenated with
259	     * its last name — and {@code CHK}, a single Luhn check digit over the digits of
260	     * {@code <REGION><FY><HASH8>} (e.g. {@code NSW263F5A9C2E4}). Aside from the fiscal year the
261	     * identity carries no sequence number, so it depends only on the owner's own postcode, telephone,
262	     * last name and registration date.
263	     *
264	     * <p>If the computed id collides with an existing owner's {@code memberId}, {@code -<n>} is
265	     * appended with the smallest {@code n} of 2 or more that makes it unique, and the de-duplicated
266	     * id is returned.
267	     */
268	    private String generateMemberId(Owner owner) {
269	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
270	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
271	        String region = Regions.forPostcode(owner.getPostcode());
272	        LocalDate registrationDate = BusinessDays.effectiveRegistrationDate(owner.getRegistrationDate());
273	        int fiscalYear = (registrationDate.getMonthValue() >= 7
274	            ? registrationDate.getYear() + 1 : registrationDate.getYear()) % 100;
275	        String prefix = String.format("%s%02d%s", region, fiscalYear, hash8(telephone + lastName));
276	        String base = prefix + luhn(prefix);
277	        return deduplicateMemberId(base, owner);
278	    }
279	
280	    /**
281	     * Return {@code base} if no other owner already uses it as a {@code memberId}; otherwise
282	     * append {@code -<n>} with the smallest {@code n >= 2} that is not already taken, so distinct
283	     * owners always receive distinct member ids.
284	     */
285	    private String deduplicateMemberId(String base, Owner owner) {
286	        Set<String> existing = ownerRepository.findAll().stream()
287	            .filter(other -> other != owner)
288	            .map(Owner::getMemberId)
289	            .filter(Objects::nonNull)
290	            .collect(Collectors.toSet());
291	        if (!existing.contains(base)) {
292	            return base;
293	        }
294	        int n = 2;
295	        while (existing.contains(base + "-" + n)) {
296	            n++;
297	        }
298	        return base + "-" + n;
299	    }
300	
301	    /**
302	     * A single Luhn check digit (0-9) over the digits contained in {@code value}; non-digit
303	     * characters (the region segment and any hex letters of the hash) are ignored. This is the
304	     * {@code CHK} segment of a {@code memberId}.
305	     */
306	    private static int luhn(String value) {
307	        int sum = 0;
308	        boolean dbl = true;
309	        for (int i = value.length() - 1; i >= 0; i--) {
310	            char c = value.charAt(i);
